import{_ as e,o as t,c as s,a6 as r}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"第一张可用图","description":"","frontmatter":{"id":"first-image","title":"第一张可用图","chapter":"00","status":"已公开","evidence_status":"按原稿重写并核对官方操作资料；未执行生图、软件操作或平台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["rembg"],"order":10,"content_kind":"操作教程","tool_ids":["tapnow","photopea","photoshop"]},"headers":[],"relativePath":"start/first-image.md","filePath":"start/first-image.md"}'),o={name:"start/first-image.md"};function p(n,a,i,l,d,h){return t(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="第一张可用图-从产品照片做到带文字的成品" tabindex="-1">第一张可用图，从产品照片做到带文字的成品 <a class="header-anchor" href="#第一张可用图-从产品照片做到带文字的成品" aria-label="Permalink to &quot;第一张可用图，从产品照片做到带文字的成品&quot;">​</a></h1><p>这篇带你完成一张厨房场景商品图，并保留可修改的文字层。准备一张自己的产品实拍，用支持上传参考图的画布生成背景，再用Photopea或PS把真实产品和文字合成进去。生成出来的候选图、可编辑源文件和最终JPG是三个不同产物，要分别保存。</p><p>沿用原稿的便携榨汁杯练习。奶油白和薄荷绿是示例颜色，你实际上传哪个SKU，就只做哪个颜色。本页没有提供实拍和实测成品，下面的文案与布局用于演示操作；功率、容量、充电方式和安全功能要用自己的资料填写。</p><h2 id="_1-先拍一张能用的照片" tabindex="-1">1. 先拍一张能用的照片 <a class="header-anchor" href="#_1-先拍一张能用的照片" aria-label="Permalink to &quot;1. 先拍一张能用的照片&quot;">​</a></h2><p>把杯子放在浅色无纹理纸或桌面上，靠窗拍摄，光从侧前方进来。关掉美颜和滤镜，擦掉杯身指纹，镜头与商品保持正常距离，再裁掉多余背景。不要用超广角贴近拍，它会把杯口和底座拍成不同大小。正面或略带侧面的照片更适合作为第一张合成素材。</p><p>打开照片放到100%检查。杯口、杯盖、按钮和底座边缘能看清，反光没有把标识烧成白块，颜色与实物接近，就可继续。只有糊图时先补拍，提示词无法恢复看不见的真实结构。</p><p>为照片取名 <code>JB01_white_front.jpg</code>，另外保留原始照片。再写四行资料。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>商品：便携榨汁杯，SKU JB01-white（示例名称）</span></span>
<span class="line"><span>本次素材：JB01_white_front.jpg，商品外观和颜色仅以该照片为准</span></span>
<span class="line"><span>本次用途：商品页场景副图，厨房台面，后期加一句准确标题</span></span>
<span class="line"><span>不添加：未核实的容量、功率、充电方式、认证和配件</span></span></code></pre></div><h2 id="_2-先做背景-再决定是否采用整图生成" tabindex="-1">2. 先做背景，再决定是否采用整图生成 <a class="header-anchor" href="#_2-先做背景-再决定是否采用整图生成" aria-label="Permalink to &quot;2. 先做背景，再决定是否采用整图生成&quot;">​</a></h2><p>以TapNow当前官方文档中的画布为操作例子。新建项目，在Add菜单建立图像节点，把产品照片作为参考输入；填写参考图用途、构图和光线，再选择画幅、模型和结果数量。先做一个方向，完成后打开全尺寸查看。<a href="https://docs.tapnow.ai/en/docs/canvas/generate-and-edit-images" target="_blank" rel="noreferrer">TapNow图像操作文档</a>。</p><p>第一遍可以尝试保留参考商品的整图生成。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>制作一张便携榨汁杯的厨房场景副图。上传的JB01_white_front.jpg是唯一商品外观依据，保留杯盖、杯体、按钮、底座、标识位置和奶油白颜色，不改变比例，不增加部件。</span></span>
<span class="line"><span>场景是明亮厨房的浅木台面，柔和自然光从左前方照入，背景略虚化。产品在画面右侧，左侧约三分之一保持简洁，留给后期标题。草莓和香蕉只作背景道具，不遮住商品，不暗示随商品发货。</span></span>
<span class="line"><span>生成一张方形图片。不要文字、数字、图标、水印和认证标识。不要打开杯盖，不生成看不见的刀头，不改变产品颜色。</span></span></code></pre></div><p>如果按钮变多、杯盖变形或包装文字被重画，停止在这张图上反复修商品。改成生成空背景，商品用原照片合成。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生成一张方形商业摄影背景，只要场景，不出现榨汁杯或其他电器。明亮厨房，浅木台面，左前方自然窗光，背景墙为奶油白。右侧留出平整无遮挡的台面，供后期放入真实商品；左侧上方留白，供标题排版。少量草莓和香蕉放在远处，不占用右侧商品区域。不生成文字、标识、杯子、瓶子或虚构产品。</span></span></code></pre></div><p>下载原图，保存成 <code>JB01_scene_background_v01.png</code>。不要把画布截图当原文件。可见结果应当是一张有空台面、有明确光向、没有假商品的背景。</p><h2 id="_3-在photopea里放回真实商品" tabindex="-1">3. 在Photopea里放回真实商品 <a class="header-anchor" href="#_3-在photopea里放回真实商品" aria-label="Permalink to &quot;3. 在Photopea里放回真实商品&quot;">​</a></h2><ol><li>打开<a href="https://www.photopea.com/" target="_blank" rel="noreferrer">Photopea</a>，用File → Open打开背景。拖入产品照片到正在编辑的画面里，形成单独图层。</li><li>给商品层命名 <code>PRODUCT_REAL</code>。选取商品，给选区添加图层蒙版，隐藏原照片背景。放大到100%修杯盖和底座边缘；操作的是蒙版，商品原像素保留。</li><li>选商品层，用Edit → Free Transform调整大小和位置，保持长宽比例。商品底座落在台面上，避免悬空；画面透视不匹配时换背景，别把杯子拉扁来迁就台面。</li><li>在商品层下面新增 <code>SHADOW</code>。用柔边低透明度黑色画笔画一块接触阴影，底座附近较紧，远处较淡。光从左侧来，阴影相应向右后方延伸。</li></ol><p>拖入图像、蒙版和变换的界面说明可见<a href="https://www.photopea.com/learn/opening-saving" target="_blank" rel="noreferrer">打开与保存</a>、<a href="https://www.photopea.com/learn/masks" target="_blank" rel="noreferrer">蒙版</a>、<a href="https://www.photopea.com/learn/free-transform" target="_blank" rel="noreferrer">自由变换</a>。透明杯体不能按不透明白盒处理，抠图后若出现黑边或失去透光，要保留合适的原背景局部或重新拍摄。</p><h2 id="_4-加一句能读清的标题" tabindex="-1">4. 加一句能读清的标题 <a class="header-anchor" href="#_4-加一句能读清的标题" aria-label="Permalink to &quot;4. 加一句能读清的标题&quot;">​</a></h2><p>选择文字工具，在左上留白拖出文本框，输入示例标题“把水果饮品带进日常”。这句话不声明未确认的性能；正式使用前确认商品适用性。标题和产品分层，副标题最多一行，颜色从产品或品牌已有颜色里选。</p><p>本练习可以用1600×1600像素工作画布，标题约90像素作为起始值。这是排版建议。把预览缩到约375像素宽，再看标题是否能读、商品是否清楚；太小就缩短标题和删文字，别继续加装饰。<a href="https://www.photopea.com/learn/text" target="_blank" rel="noreferrer">Photopea文字工具</a>。</p><h2 id="_5-保存后重新打开" tabindex="-1">5. 保存后重新打开 <a class="header-anchor" href="#_5-保存后重新打开" aria-label="Permalink to &quot;5. 保存后重新打开&quot;">​</a></h2><p>File → Save as PSD保存 <code>JB01_scene_v01.psd</code>，再用File → Export As → JPG导出预览。重新打开PSD，确认文字仍能编辑、商品蒙版存在；重新打开JPG，确认边缘、标题和颜色。Photoshop对应步骤也是商品层、蒙版、阴影层、文字层，具体入口参见<a href="https://helpx.adobe.com/photoshop/desktop/crop-resize-transform/transform-manipulate-reshape/combine-images-in-photoshop.html" target="_blank" rel="noreferrer">合成图像</a>。</p><table tabindex="0"><thead><tr><th>看到的问题</th><th>本次该改哪一步</th></tr></thead><tbody><tr><td>商品悬空</td><td>第3步把底座放回台面，重做接触阴影</td></tr><tr><td>杯子变宽</td><td>回原商品层，恢复等比变换</td></tr><tr><td>标识糊了</td><td>用实拍商品层，取消对商品的生成或过度锐化</td></tr><tr><td>标题被水果挡住</td><td>只调整背景道具或标题区，不重新画商品</td></tr><tr><td>手机预览字太小</td><td>缩短标题，扩大文字，移走次要说明</td></tr></tbody></table><p>接着做<a href="./../ecommerce/image-set">一套商品图</a>。需要改写同类场景时查<a href="./../prompts/P01">P01完整模板</a>；本页的两条提示词已经可以直接复制，不必先跳到模板页才能开始。</p>`,25)])])}const m=e(o,[["render",p]]);export{_ as __pageData,m as default};
